export default function PitWall({frame,onChannels,year,round,offset,time,drivers,coordinates,selected,onSelect,duration,playing,onTime,onToggle}: {frame:UnifiedRaceState;onChannels:(channels:Channels)=>void;duration:number;playing:boolean;onTime:(time:number)=>void;onToggle:()=>void;year:number;round:number;offset:number;time:number;drivers:Driver[];coordinates:[number,number][];selected:number|null;onSelect:(number:number)=>void}){
 const driver=drivers.find(d=>d.driver_number===selected)||drivers[0];
 const [data,setData]=useState<Data|null>(null),[error,setError]=useState(''),[revision,setRevision]=useState(0);
 useEffect(()=>{if(!driver)return;const controller=new AbortController();setData(null);setError('');apiFetch(`/api/replay/multi?year=${year}&round=${round}&start=${offset}&pitwall_driver=${driver.driver_number}`,{signal:controller.signal}).then(async r=>{const d=await r.json().catch(()=>null);if(!r.ok||!d?.channels)throw Error(d?.detail||'Recorded pit-wall channels could not be loaded.');return d;}).then(d=>{if(!controller.signal.aborted){setData(d);onChannels(d.channels);}}).catch(e=>{if(!controller.signal.aborted)setError(e.message);});return()=>controller.abort();},[year,round,offset,driver?.driver_number,revision,onChannels]);
 if(!driver)return null;
