 const drs=value(fresh,'drs');const drsLabel=drsStatus(drs);
 const events=rows('race_control').filter(r=>r.time<=time).slice(-5).reverse();const radio=rows('team_radio').filter(r=>r.time<=time).slice(-4).reverse();const weather=latest(rows('weather'),time);
 const xs=coordinates.map(p=>p[0]),ys=coordinates.map(p=>p[1]);const minX=Math.min(...xs),minY=Math.min(...ys),span=Math.max(Math.max(...xs)-minX,Math.max(...ys)-minY,1);const xy=(x:number,y:number)=>[20+(x-minX)/span*360,380-(y-minY)/span*360];
