 <div className="pw-controls"><button onClick={onToggle}>{playing?'Pause pit wall':'Play pit wall'}</button><input type="range" min={0} max={duration} step={0.05} value={time} onChange={e=>onTime(Number(e.target.value))} aria-label="Pit wall replay timeline"/><span>{Math.floor(time)} / {Math.floor(duration)}s</span></div><div className="pw-grid"><div className="pw-card"><h3>Circuit tracker</h3><svg viewBox="0 0 400 400" className="pw-map" aria-label="Recorded driver positions"><polyline points={coordinates.map(p=>xy(...p).join(',')).join(' ')} fill="none" stroke="#344960" strokeWidth="9" strokeLinejoin="round"/><polyline points={coordinates.map(p=>xy(...p).join(',')).join(' ')} fill="none" stroke="#a2b5c9" strokeWidth="2"/>{drivers.map(d=>{const pose=frame.cars.find(c=>c.driverNumber===d.driver_number)?.pose;if(!pose)return null;const [x,y]=xy(pose.x,pose.y);return <g key={d.driver_number} role="button" tabIndex={0} aria-label={`Track ${d.name}`} onClick={()=>onSelect(d.driver_number)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onSelect(d.driver_number);}}} style={{cursor:'pointer'}}><circle cx={x} cy={y} r={d.driver_number===driver.driver_number?8:5} fill={d.color} stroke="#fff" strokeWidth={d.driver_number===driver.driver_number?2:0}/><text x={x+9} y={y-7} fill="white" fontSize="10">{d.code}</text></g>;})}</svg><small className="pw-muted">Recorded positions; gaps over two seconds are hidden.</small></div>
