import {apiFetch} from '../helpers/apiFetch';
import {useEffect,useState} from 'react';

type Item={title:string;url:string;published_at:string;source:string;audio_url?:string|null;duration?:string};
type Feed={items:Item[];updated_at:string|null;stale:boolean;error:string|null};
type News={checked_at:string;feeds:{headlines:Feed;radio:Feed}};
const date=(value:string)=>new Date(value).toLocaleString(undefined,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
function RadioEpisode({item}:{item:Item}){const [failed,setFailed]=useState(false);return <article className="news-episode"><small>{date(item.published_at)}</small><h4>{item.title}</h4>{item.audio_url&&!failed?<audio controls preload="none" src={item.audio_url} onError={()=>setFailed(true)}/>:<p>Audio unavailable here. Listen on the BBC.</p>}<a href={item.url} target="_blank" rel="noreferrer">Open episode on BBC ↗</a></article>;}
export default function NewsDesk(){
 const [data,setData]=useState<News|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[expanded,setExpanded]=useState(false),[revision,setRevision]=useState(0);
 useEffect(()=>{const controller=new AbortController();let active=false;
 const load=async()=>{if(active||controller.signal.aborted)return;active=true;setBusy(true);try{const response=await apiFetch('/api/news',{signal:controller.signal,cache:'no-store'});if(!response.ok)throw Error('News could not be refreshed. Try again shortly.');const next=await response.json();if(!next?.feeds?.headlines||!next?.feeds?.radio)throw Error('The news feed returned an unexpected response.');if(!controller.signal.aborted){setData(next);setError('');}}catch(e){if(!controller.signal.aborted)setError(e instanceof Error?e.message:'News unavailable');}finally{active=false;if(!controller.signal.aborted)setBusy(false);}};
 load();const timer=window.setInterval(()=>{if(!document.hidden)void load();},180000);const visible=()=>{if(!document.hidden)void load();};document.addEventListener('visibilitychange',visible);return()=>{controller.abort();clearInterval(timer);document.removeEventListener('visibilitychange',visible);};},[revision]);
 const news=data?.feeds.headlines,radio=data?.feeds.radio;
 return <section className="news-desk" aria-label="F1 news and radio"><div className="news-top"><div><div className="eyebrow">THE PADDOCK DESK</div><h2>F1 news & radio</h2></div><div className="news-actions"><span>CHECKS EVERY 3 MIN</span><button disabled={busy} onClick={()=>setRevision(n=>n+1)}>{busy?'Refreshing…':'Refresh news'}</button></div></div><p className="news-muted">Latest publisher headlines, race commentary links and F1 audio. News follows today’s date, including when you browse an older season.</p>{error&&<p role="alert">{error}{data?' Previously loaded headlines remain below.':''}</p>}{news?.stale&&<p role="status">{news.error}</p>}{!data&&!error&&<p role="status">Loading the paddock headlines…</p>}<div className="news-grid">{news?.items.slice(0,expanded?12:3).map(item=><article className="news-story" key={item.url}><small>{item.source} · {date(item.published_at)}</small><h3><a href={item.url} target="_blank" rel="noreferrer">{item.title} <span>↗</span></a></h3><span className="news-read">READ AT BBC SPORT</span></article>)}</div><div className="news-links">{news&&news.items.length>3&&<button onClick={()=>setExpanded(x=>!x)}>{expanded?'Show fewer headlines':'More headlines & radio episodes'}</button>}<a href="https://www.bbc.co.uk/sport/formula1" target="_blank" rel="noreferrer">BBC Sport F1 ↗</a><small>{news?.updated_at?`${news.stale?'Saved':'Fetched'} ${date(news.updated_at)} · publisher delivery may be delayed`:'Waiting for publisher feed'}</small></div><div className="news-radio"><div><div className="eyebrow">LISTEN TO THE RACE WEEKEND</div><h3>F1 on the radio</h3><p>Open BBC commentary and the session schedule. Coverage is available during scheduled sessions; UK and account restrictions can apply.</p><div className="news-links"><a className="news-listen" href="https://www.bbc.co.uk/programmes/b007m6lj" target="_blank" rel="noreferrer">Commentary & schedule ↗</a><a href="https://www.bbc.co.uk/sounds/play/live:bbc_radio_five_live" target="_blank" rel="noreferrer">Open BBC Radio 5 Live ↗</a></div><small>These links open the broadcaster. Team-radio clips remain in the recorded race pit wall.</small></div><div><h3>Latest Chequered Flag</h3>{radio?.stale&&<p>{radio.error}</p>}{radio?.items.slice(0,expanded?4:1).map(item=><RadioEpisode key={item.url} item={item}/>)}{radio&&!radio.items.length&&<p>Episodes are temporarily unavailable.</p>}<p className="news-muted">Podcast audio plays on request and is separate from race commentary.</p></div></div><p className="news-muted">Headlines: <a href="https://feeds.bbci.co.uk/sport/formula1/rss.xml" target="_blank" rel="noreferrer">BBC Sport RSS</a> · Audio: <a href="https://www.bbc.co.uk/programmes/p02nrsjn" target="_blank" rel="noreferrer">BBC Radio 5 Live</a>. Publication times are shown in your local time.</p></section>;
