import StrategyTools from '../components/StrategyTools';
import React, { useRef, useState } from 'react';
import EngineeringShowcase from '../components/EngineeringShowcase';
import { ASSUMPTION_PROFILES, baselineComparison, scenarioForRace, COMPOUNDS, DEFAULT_SCENARIO, briefing, duration, planWarnings, simulate, validateScenario } from '../helpers/strategyModel';
import type { Compound, Conditions, Plan, Scenario, RaceContext } from '../helpers/strategyModel';
const STORAGE='f1-strategy-lab.scenarios.v1';
const copy=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
function download(name:string,text:string,type:string){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function loadSaved():Scenario[]{try{const data=JSON.parse(localStorage.getItem(STORAGE)||'[]');if(!Array.isArray(data))return [];return data.filter(s=>{try{validateScenario(s);return true;}catch{return false;}});}catch{return [];}}
function PlanEditor({plan,index,laps,onChange}:{plan:Plan;index:number;laps:number;onChange:(p:Plan)=>void}){
 const [pitText,setPitText]=useState(plan.pits.join(', '));
 return <section className="strategy-card"><h3>Plan {index===0?'A':'B'}</h3>
  <label>Plan name<input maxLength={100} value={plan.name} onChange={e=>onChange({...plan,name:e.target.value})}/></label>
  <label>Stops<select value={plan.compounds.length-1} onChange={e=>{const count=Number(e.target.value);const pits=Array.from({length:count},(_,i)=>Math.round(laps*(i+1)/(count+1)));setPitText(pits.join(', '));onChange({...plan,pits,compounds:Array.from({length:count+1},(_,i)=>plan.compounds[i]||'hard')});}}>{[0,1,2,3].map(n=><option key={n} value={n}>{n}</option>)}</select></label>
  {plan.pits.length>0&&<label>Pit at end of laps (comma separated)<input value={pitText} onChange={e=>{setPitText(e.target.value);onChange({...plan,pits:e.target.value.split(',').map(v=>v.trim()===''?NaN:Number(v.trim()))});}}/><small>Enter {plan.compounds.length-1} increasing laps, between 1 and {laps-1}.</small></label>}
  <div className="strategy-grid">{plan.compounds.map((compound,i)=><label key={i}>Stint {i+1}<select value={compound} onChange={e=>onChange({...plan,compounds:plan.compounds.map((v,j)=>j===i?e.target.value as Compound:v)})}>{COMPOUNDS.map(c=><option key={c} value={c}>{c}</option>)}</select></label>)}</div>
 </section>;
}
export default function StrategyWorkbench({onBack,race}:{onBack:()=>void;race?:RaceContext}){
 const [scenario,setScenario]=useState<Scenario>(()=>scenarioForRace(race));
 const [saved,setSaved]=useState<Scenario[]>(loadSaved);
 const [message,setMessage]=useState('');
 const [revision,setRevision]=useState(0);
 const [showEngineering,setShowEngineering]=useState(false);
 const input=useRef<HTMLInputElement>(null);
 let error='';try{validateScenario(scenario);}catch(e){error=(e as Error).message;}
 const results=error?null:scenario.plans.map(p=>simulate(p,scenario.conditions));
 const totals=results?.map(r=>r[r.length-1].cumulative);
 const c=scenario.conditions;
 const baseline=error?null:baselineComparison(scenario);
 const recordedLapUsed=scenario.race?.recordedLaps===c.laps;
 const referencePace=scenario.race?.fastestLapSeconds;
 const referencePaceUsed=referencePace!==undefined && Math.round((referencePace+5)*10)/10===c.baseLap;
 const changeCondition=(key:keyof Conditions,value:number)=>setScenario(s=>({...s,conditions:{...s.conditions,[key]:value,...(key==='laps'?{rainLap:Math.min(s.conditions.rainLap,value),safetyLap:Math.min(s.conditions.safetyLap,value)}:{})}}));
 const changePlan=(index:number,plan:Plan)=>setScenario(s=>({...s,plans:s.plans.map((p,i)=>i===index?plan:p) as [Plan,Plan]}));
 function apply(s:Scenario){setScenario(copy(s));setRevision(n=>n+1);setMessage(`Loaded “${s.name}”.`);}
 function persist(next:Scenario[]){try{localStorage.setItem(STORAGE,JSON.stringify(next));setSaved(next);return true;}catch{setMessage('Browser storage is unavailable or full. Export JSON to keep this scenario.');return false;}}
 function save(){if(error)return;const next=[copy(scenario),...saved.filter(s=>s.name!==scenario.name)].slice(0,30);if(persist(next))setMessage(`Saved “${scenario.name}” in this browser. Saving the same name replaces it.`);}
 const fields: {key:keyof Conditions;label:string;min:number;max:number;step:number}[]=[{key:'laps',label:'Race laps',min:2,max:100,step:1},{key:'baseLap',label:'Baseline lap time (seconds)',min:40,max:200,step:.1},{key:'pitLoss',label:'Normal pit loss (seconds)',min:5,max:60,step:.5},{key:'degradation',label:'Tyre degradation multiplier',min:0,max:3,step:.05},{key:'rain',label:'Rain intensity (%)',min:0,max:100,step:5},{key:'rainLap',label:'Rain starts on lap',min:1,max:c.laps,step:1},{key:'safetyLap',label:'Safety car starts on lap (0 = off)',min:0,max:c.laps,step:1},{key:'safetyDuration',label:'Safety-car duration (laps)',min:1,max:10,step:1}];
 const gap=results?results[0].map((r,i)=>r.cumulative-results[1][i].cumulative):[];
 const extent=Math.max(1,...gap.map(Math.abs));
 const filename=scenario.name.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'race-scenario';
 return <div className="app"><header><div className="logo"><span className="logo-mark">F1</span> STRATEGY <span className="muted">LAB</span></div><span className="phase">STRATEGY WORKBENCH</span></header><main className="strategy">
  <button onClick={onBack}>← Race archive</button>
  <div className="intro"><div><div className="eyebrow">EXPLORE · COMPARE · SAVE</div><h1>Build your race.</h1><p>Compare two plans under the same conditions. Educational estimates with illustrative coefficients.</p></div></div>
  {scenario.race&&<section className="strategy-card"><div className="eyebrow">RACE CONTEXT · ARCHIVE REFERENCE</div><h2>{scenario.race.name} · {scenario.race.season}</h2><p>{scenario.race.circuit} · Round {scenario.race.round} · {scenario.race.date}</p><p className="strategy-muted">{recordedLapUsed?`Using the winner's recorded ${c.laps}-lap distance; this may be shorter than the scheduled race.`:`Race length is an editable assumption (${c.laps} laps).`}{' '}{referencePaceUsed?`Initial pace uses the winner's fastest lap (${referencePace}s) plus an illustrative 5-second margin.`:'Baseline pace is an editable estimate.'} Pit loss and degradation are example assumptions.</p><div className="strategy-actions"><button onClick={()=>apply(scenarioForRace(scenario.race))}>Restore race starting assumptions</button><button onClick={()=>{setScenario(s=>{const {race:_,...rest}=s;return rest;});setMessage('Race context removed; your plans and conditions are unchanged.');}}>Detach race context</button></div></section>}
  <section className="strategy-card"><h2>Circuit assumptions</h2><p className="strategy-muted">Choose a starting point for pit loss and tyre wear, then edit the numbers below. These examples are not measured circuit presets. Applying one keeps your laps, pace, weather and pit plans.</p><div className="strategy-actions">{ASSUMPTION_PROFILES.map(profile=><button key={profile.id} onClick={()=>{setScenario(s=>({...s,conditions:{...s.conditions,pitLoss:profile.pitLoss,degradation:profile.degradation}}));setMessage(`Applied ${profile.label}: ${profile.pitLoss}s pit loss, ${profile.degradation}× degradation.`);}}>{profile.label}</button>)}</div></section>
  <section className="strategy-card"><h2>Race conditions</h2><div className="strategy-grid">{fields.map(f=><label key={f.key}>{f.label}<input type="number" min={f.min} max={f.max} step={f.step} value={Number.isFinite(c[f.key])?c[f.key]:''} onChange={e=>changeCondition(f.key,e.target.value===''?NaN:Number(e.target.value))}/></label>)}</div><p className="strategy-muted">Rain stays constant after its start lap. Safety-car timing is shared by both plans; pit loss falls to 55% during those laps. Plans keep the compounds you choose.</p></section>
  <div className="strategy-grid">{scenario.plans.map((plan,i)=><PlanEditor key={`${revision}-${i}`} plan={plan} index={i} laps={c.laps} onChange={p=>changePlan(i,p)}/>)}</div>
  {!error&&<StrategyTools scenario={scenario} onApply={(index,plan)=>{changePlan(index,plan);setRevision(n=>n+1);setMessage(`Applied optimised plan ${index===0?'A':'B'}. Save the scenario to keep it.`);}}/>}
  {error&&<p role="alert" className="strategy-error">{error}</p>}
  {results&&totals&&<section className="strategy-card"><h2>Strategy comparison</h2><div className="strategy-grid">{scenario.plans.map((p,i)=><div key={i} className="strategy-total"><span>{p.name}</span><strong>{duration(totals[i])}</strong>{planWarnings(p,c).map(w=><p key={w} className="strategy-warning">{w}</p>)}</div>)}</div>
   <p role="status">{Math.abs(totals[0]-totals[1])<.05?'The plans are effectively tied.':`${scenario.plans[totals[0]<totals[1]?0:1].name} is ${Math.abs(totals[0]-totals[1]).toFixed(1)} seconds quicker in this model.`}</p>
   {baseline&&<details open><summary>Effect of conditions against a dry baseline</summary><p className="strategy-muted">Same compounds, pit laps and assumptions; baseline has no rain and no safety car. Positive change means slower. Wet tyres remain fitted if you selected them.</p><div style={{overflowX:'auto'}}><table><thead><tr><th>Plan</th><th>Dry baseline</th><th>Current conditions</th><th>Change</th></tr></thead><tbody>{baseline.map((r,i)=><tr key={i}><td>{r.name}</td><td>{duration(r.baseline)}</td><td>{duration(r.actual)}</td><td>{r.difference>=0?'+':''}{r.difference.toFixed(1)}s</td></tr>)}</tbody></table></div></details>}
   <h3>Cumulative gap · A minus B</h3><p className="strategy-muted">Above zero: B leads. Below zero: A leads. Pit stops appear as steps in the gap.</p>
   <svg viewBox="0 0 800 240" role="img" aria-label="Cumulative time gap between plan A and plan B by lap" style={{width:'100%',maxHeight:300,background:'#0a131f',borderRadius:10}}><line x1="65" y1="110" x2="775" y2="110" stroke="#687992" strokeDasharray="5 5"/><text x="8" y="25" fill="#b9cbe2" fontSize="13">+{extent.toFixed(0)}s</text><text x="8" y="114" fill="#b9cbe2" fontSize="13">0s</text><text x="8" y="207" fill="#b9cbe2" fontSize="13">−{extent.toFixed(0)}s</text><polyline fill="none" stroke="#60d8cb" strokeWidth="3" points={gap.map((g,i)=>`${65+i/(gap.length-1)*710},${110-g/extent*90}`).join(' ')}/><text x="65" y="232" fill="#b9cbe2" fontSize="13">Lap 1</text><text x="710" y="232" fill="#b9cbe2" fontSize="13">Lap {c.laps}</text></svg>
   <details><summary>Lap-by-lap timings</summary><div style={{overflowX:'auto'}}><table><thead><tr>{['Lap','A tyre','A lap (s)','A total (s)','B tyre','B lap (s)','B total (s)','Conditions'].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{results[0].map((a,i)=>{const b=results[1][i];return <tr key={a.lap}><td>{a.lap}</td><td>{a.compound}{a.pit?' · PIT':''}</td><td>{a.seconds.toFixed(2)}</td><td>{a.cumulative.toFixed(2)}</td><td>{b.compound}{b.pit?' · PIT':''}</td><td>{b.seconds.toFixed(2)}</td><td>{b.cumulative.toFixed(2)}</td><td>{a.safety?'Safety car ':''}{c.rain>0&&a.lap>=c.rainLap?'Rain':''}</td></tr>;})}</tbody></table></div></details>
  </section>}
  <section className="strategy-card"><h2>Save & share</h2><label>Scenario name<input maxLength={100} value={scenario.name} onChange={e=>setScenario(s=>({...s,name:e.target.value}))}/></label><div className="strategy-actions"><button disabled={!!error} onClick={save}>Save in this browser</button><button disabled={!!error} onClick={()=>download(`${filename}.json`,JSON.stringify(scenario,null,2),'application/json')}>Export scenario JSON</button><button disabled={!!error} onClick={()=>download(`${filename}-briefing.md`,briefing(scenario),'text/markdown')}>Export race briefing</button><button disabled={!!error} onClick={async()=>{try{await navigator.clipboard.writeText(briefing(scenario));setMessage('Race briefing copied. Paste it into Notes, an email or a document.');}catch{setMessage('Clipboard access is unavailable. Use Export race briefing instead.');}}}>Copy race briefing</button><button onClick={()=>input.current?.click()}>Import scenario JSON</button><button onClick={()=>apply(DEFAULT_SCENARIO)}>Reset example</button></div>
   <input ref={input} type="file" accept=".json,application/json" hidden onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>100000)throw Error('Choose a scenario JSON smaller than 100 KB.');const s=JSON.parse(await file.text());validateScenario(s);apply(s);}catch(err){setMessage(`Import failed: ${(err as Error).message}`);}e.target.value='';}}/>
   <p role="status">{message}</p><p className="strategy-muted">Up to 30 named scenarios are kept in this browser. JSON exports let you transfer them or keep a separate copy.</p>
   {saved.map(s=><div key={s.name} className="strategy-saved"><span>{s.name}{s.race&&<small style={{display:'block'}}>{s.race.season} · {s.race.circuit}</small>}</span><button onClick={()=>apply(s)}>Load</button><button onClick={()=>{if(persist(saved.filter(v=>v.name!==s.name)))setMessage(`Deleted saved scenario “${s.name}”.`);}}>Delete</button></div>)}
  </section>
  <section className="strategy-card"><h2>Engineering → strategy</h2><p>Inspect tyres, wings and the power unit to see how their behaviour informs race decisions.</p><button aria-expanded={showEngineering} onClick={()=>setShowEngineering(v=>!v)}>{showEngineering?'Hide':'Open'} engineering viewer</button>{showEngineering&&<div style={{marginTop:16}}><EngineeringShowcase driverName="Strategy driver"/></div>}</section>
  <details className="strategy-card"><summary>Model assumptions</summary><p>Tyre age adds a linear time penalty; new tyres reset age. No traffic, overtaking, fuel burn, temperature, track evolution, red flags are simulated. Pit-lap optimisation searches only the compound sequences and stop counts you supply. Slick rain penalties scale with intensity. Intermediate and wet tyres carry dry-track penalties. These example coefficients are not calibrated to any circuit, season or driver.</p><p>Changing race length may require you to update pit laps. Tyre-rule notes prompt a check of event rules; they do not validate regulatory eligibility.</p></details>
 </main></div>;
}

