import React, { useMemo, useState } from 'react';
import {strategyUncertainty,duration,optimisePitLaps,recommendation,sensitivity,stintTimeline} from '../helpers/strategyModel';
import type {Plan,Scenario,RankedPlan,Compound} from '../helpers/strategyModel';
const colours:Record<Compound,string>={soft:'#cc4356',medium:'#b79121',hard:'#8495ac',intermediate:'#237b5b',wet:'#325ead'};
export default function StrategyTools({scenario,onApply}:{scenario:Scenario;onApply:(index:number,plan:Plan)=>void}){
 const [minStint,setMinStint]=useState(3);
 const [search,setSearch]=useState<{signature:string;rows:RankedPlan[]}|null>(null);
 const [notice,setNotice]=useState('');
 const signature=JSON.stringify({conditions:scenario.conditions,plans:scenario.plans,minStint});
 const current=search?.signature===signature;
 const checks=sensitivity(scenario);
 const uncertainty=useMemo(()=>strategyUncertainty(scenario),[scenario]);
 function run(){try{const rows=optimisePitLaps(scenario,minStint);setSearch({signature,rows});setNotice(rows.length?`Found ${rows.length} ranked alternatives. Your plans are unchanged until you apply one.`:'No feasible schedules. Reduce the minimum stint length or the number of stops.');}catch(e){setNotice((e as Error).message);}}
 return <>
  <section className="strategy-card"><h2>Tyre-stint timelines</h2><p className="strategy-muted">Stops happen at the end of a stint. Each block shows its compound and inclusive lap range.</p>{scenario.plans.map((p,i)=><div key={i} style={{marginBottom:18}}><h3>{i===0?'A':'B'} · {p.name}</h3><div style={{display:'flex',gap:3,minHeight:40}} role="img" aria-label={stintTimeline(p,scenario.conditions.laps).map(s=>`${s.compound}, laps ${s.start} to ${s.end}`).join('; ')}>{stintTimeline(p,scenario.conditions.laps).map((s,j)=><div key={j} style={{flex:s.length,background:colours[s.compound],borderRadius:5,minWidth:2}} title={`${s.compound}: laps ${s.start}–${s.end}`}/>)}</div><p style={{fontSize:13,lineHeight:1.8}}>{stintTimeline(p,scenario.conditions.laps).map(s=>`${s.compound}: ${s.start}–${s.end} (${s.length} laps)`).join(' → ')}</p></div>)}</section>
  <section className="strategy-card"><h2>Find better pit laps</h2><p className="strategy-muted">Searches every feasible lap schedule for each of your two compound sequences and stop counts. Shows up to five results per sequence, ranked together. Compounds stay fixed. Minimum stint length applies to every stint, including the first and last. This uses the educational model and does not validate race rules.</p><label>Minimum stint length (laps)<input type="number" min={1} max={20} step={1} value={Number.isFinite(minStint)?minStint:''} onChange={e=>setMinStint(e.target.value===''?NaN:Number(e.target.value))}/></label><button onClick={run}>Search pit strategies</button><p role="status">{!current&&search?'Inputs changed. Run the search again for current results.':notice}</p>
   {current&&search&&search.rows.length>0&&<div style={{overflowX:'auto'}}><table><thead><tr><th>Rank</th><th>From</th><th>Compounds</th><th>Pit laps</th><th>Total</th><th>Gain vs source</th><th>Apply</th></tr></thead><tbody>{search.rows.map((r,i)=><tr key={i}><td>{i+1}</td><td>{r.source===0?'A':'B'}</td><td>{r.plan.compounds.join(' → ')}</td><td>{r.plan.pits.join(', ')||'No stops'}</td><td>{duration(r.total)}</td><td>{r.gain.toFixed(2)}s{r.gain<0?' slower':''}</td><td><div className="strategy-actions">{[0,1].map(target=><button key={target} aria-label={`Apply rank ${i+1} to plan ${target===0?'A':'B'}`} onClick={()=>{onApply(target,{...r.plan,name:`Optimised plan ${target===0?'A':'B'}`,pits:[...r.plan.pits],compounds:[...r.plan.compounds]});setNotice(`Applied rank ${i+1} to plan ${target===0?'A':'B'}. Save your scenario to keep it.`);}}>Use as {target===0?'A':'B'}</button>)}</div></td></tr>)}</tbody></table></div>}
  </section>
  <section className="strategy-card"><h2>Strategy uncertainty forecast</h2><p className="strategy-muted">200 paired scenario samples: tyre wear ±20%, pit loss ±5s, rain onset ±3 laps, and rain intensity ±10 percentage points when rain is enabled. Inputs are clamped to supported ranges. Same conditions apply to both plans; safety-car timing stays fixed. Sample shares are not calibrated real-race probabilities or a trained tyre model.</p><div className="strategy-grid">{scenario.plans.map((p,i)=><div key={i} className="strategy-total"><span>{p.name}</span><strong>{(i===0?uncertainty.aShare:uncertainty.bShare).toFixed(1)}% of samples led</strong><p>Mean: {duration(uncertainty.summaries[i].mean)}</p><small>Central 80% of sampled totals: {duration(uncertainty.summaries[i].low)} – {duration(uncertainty.summaries[i].high)}</small></div>)}</div><p>{uncertainty.tieShare.toFixed(1)}% tied. Estimates use your plans and this app's illustrative tyre model.</p></section>
  <section className="strategy-card"><h2>Strategy recommendation</h2><p>{recommendation(scenario)}</p><details open><summary>Sensitivity checks</summary><p className="strategy-muted">Same plans under small changes to wear, pit loss and rain timing. Bounds can make some checks identical; rain-timing changes have no effect while rain is off.</p><div style={{overflowX:'auto'}}><table><thead><tr><th>Check</th><th>Plan A</th><th>Plan B</th><th>Lead</th></tr></thead><tbody>{checks.map(r=><tr key={r.label}><td>{r.label}</td><td>{duration(r.a)}</td><td>{duration(r.b)}</td><td>{r.winner===null?'Tie':`${r.winner===0?'A':'B'} by ${Math.abs(r.gap).toFixed(1)}s`}</td></tr>)}</tbody></table></div></details><p className="strategy-muted">The recommendation and sensitivity table are included when you export or copy the race briefing.</p></section>
 </>;
}

