  <Sky distance={900} sunPosition={daylight?[100,70,40]:[100,8,-80]} turbidity={daylight?6:12} rayleigh={2}/>
  <hemisphereLight args={['#d6e7ff','#74755b',daylight?1.3:.5]}/>
