  flat.children.forEach(o=>(o as THREE.Mesh).geometry.applyMatrix4(turn));
  const box=new THREE.Box3().setFromObject(flat),size=box.getSize(new THREE.Vector3()),centre=box.getCenter(new THREE.Vector3());
